	def ("integrate_sin", integrate_sin);	// make integrate_sin() visible to python
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define GPIO_NUMBER "4"
#define GPIO4_PATH "/sys/class/gpio/gpio4/"
#define GPIO_SYSFS "/sys/class/gpio/"

void writeGPIO(char filename[], char value[]) {
    FILE* fp;                                       // create a file pointer fp
    fp = fopen(filename, "w+");                     // open file for write/update
    fprintf(fp, "%s", value);                       // send the value to the file
    fclose(fp);
}

int main(int argc, char* argv[]) {
    if (argc != 2) {                                // program name is argument 1
        printf("Usage is makeLEDC and one of:\n");
        printf("    setup, on, off, status, or close\n");
        printf("    e.g. makeLEDC on\n");
        return 2;                                   // invalid number of arguments
    }

    printf("Starting the makeLED program\n");
    if (strcmp(argv[1], "setup") == 0) {
        printf("Setting up the LED on the GPIO\n");
        writeGPIO(GPIO_SYSFS "export", GPIO_NUMBER);
        usleep(100000);                             // sleep for 100ms
        writeGPIO(GPIO4_PATH "direction", "out");
    }
    else if (strcmp(argv[1], "close") == 0) {
        printf("Closing the LED on the GPIO\n");
        writeGPIO(GPIO_SYSFS "unexport", GPIO_NUMBER);
    }
    else if (strcmp(argv[1], "on") == 0) {
        printf("Turning the LED on\n");
        writeGPIO(GPIO4_PATH "value", "1");
    }
    else if (strcmp(argv[1], "off") == 0) {
        printf("Turning the LED off\n");
        writeGPIO(GPIO4_PATH "value", "0");
    }
    else if (strcmp(argv[1], "status") == 0) {
        FILE *fp;                                   // file pointer
        char line[80], fullFilename[100];
        sprintf(fullFilename, GPIO4_PATH "/value");
        fp = fopen(fullFilename, "rt");             // read text
        while (fgets(line, 80, fp) != NULL) {
            printf("The state of the LED is %s", line);
        }
        fclose(fp);
    }
    else {
        printf("Invalid command!\n");
    }
    printf("Finished the makeLED Program\n");
    return 0;
}

#include <iostream>
#include <fstream>
#include <string>
#include <unistd.h>				// for the microsecond sleep function
using namespace std;

#define GPIO		"/sys/class/gpio/"
#define FLASH_DELAY	50000 			// 50 milliseconds i.e. 50 X 1000 microseconds

class LED{
	private:				// the following is part of the implementation
		string 	gpioPath;		// private states
		int 	gpioNumber;
		void	writeSysfs (string path, string filename, string value);
	public:					// part of the public interface
		LED (int gpioNumber);		// the constructor - create the object
		virtual void turnOn();
		virtual void turnOff();
		virtual void displayState();
		virtual ~LED();			// the destructor -- called automatically
};

LED::LED(int gpioNumber){			// constructor implementation
	this -> gpioNumber = gpioNumber;
	gpioPath = string(GPIO "gpio") + to_string(gpioNumber) + string("/");
	writeSysfs(string(GPIO), "export", to_string(gpioNumber));
	usleep(100000);				// ensure GPIO is exported
	writeSysfs(gpioPath, "direction", "out");
}

// This implementation function is "hidden" from outside the class
void LED::writeSysfs(string path, string filename, string value){
	ofstream fs;
	fs.open((path+filename).c_str());
	fs << value;
	fs.close();
}

void LED::turnOn(){
	writeSysfs(gpioPath, "value", "1");
}

void LED::turnOff(){
	writeSysfs(gpioPath, "value", "0");
}

void LED::displayState(){
	ifstream fs;
	fs.open((gpioPath + "value").c_str());
	string line;
	cout << "The current LED state is ";
	while (getline(fs, line)) cout << line << endl;
	fs.close();
}

LED::~LED(){				// The destructor unexports the sysfs GPIO entries
	cout << "Destroying the LED with GPIO number " << gpioNumber << endl;
	writeSysfs(string(GPIO), "unexport", to_string(gpioNumber));
}

int main(int argc, char* argv[]){	// the main function start point
	cout << "Starting the makeLEDs program" << endl;
	LED led1(4), led2(17);		// create two LED objects
	cout << "Flashing the LEDs for 5 seconds" << endl;
	for (int i=0; i<50; i++){	// LEDs will alternate
		led1.turnOn();		// turn GPIO4 on
		led2.turnOff();		// turn GPIO17 off
		usleep(FLASH_DELAY);	// sleep for 50ms
		led1.turnOff();		// turn GPIO4 off
		led2.turnOn();		// turn GPIO17 on
		usleep(FLASH_DELAY);	// sleep for 50 ms
	}
	led1.displayState();		// display final GPIO4 state
	led2.displayState();		// display final GPIO17 state
	cout << "Finished the makeLEDs program"  << endl;
	return 0;
}

#include <iostream>
using namespace std;

typedef int (*CallbackType)(int);           // used to tidy up syntax

int squareCallback(int x){                  // callback function that squares
    return x*x;
}

int cubeCallback(int x){                    // callback function that cubes
    return x*x*x;
}

int doMath(int num, CallbackType callback){
    return callback(num);                   // call the function that is passed
}

int main(){
    cout << "Math program -- the value of 5: " << endl;
    cout << "-> squared is: " << doMath(5, &squareCallback) << endl;
    cout << "-> cubed is: " << doMath(5, &cubeCallback) << endl;
    return 0;
}

#include <iostream>
#include <pthread.h>
#include <unistd.h>
using namespace std;

// This is the thread function that executes when the thread is created
// it passes and receives data by void pointers
void *threadFunction(void *value){
    int *x = (int *)value;              // cast the data passed to an int pointers
    while (*x < 5) {                    // while the value of x is less than 5
        usleep(10);                     // sleep for 10us - encourage main thread
        (*x) ++;                        // increment the value of x by 1
    }
    return x;                           // return the pointer x (as a void*)
}

int main (){
    int x=0, y=0;
    pthread_t thread;                   // this is our handle to pthread
    // create the thread, pass the reference, address of the function and data
    // pthread_create() returns 0 on the successful creation of a thread
    if (pthread_create(&thread, NULL, &threadFunction, &x) != 0) {
        cout << "Failed to create the thread" << endl;
        return 1;
    }
    // at this point the thread was created successfully
    while (y<5){                        // loop and increment y, displaying values
        cout << "The value of x=" << x << " and y=" << y++ << endl;
        usleep(10);
    }
    void* result;                       // OPTIONAL: receive data back from pthread
    pthread_join(thread, &result);      // allow the pthread to complete
    int *z = (int *) result;            // cast the void* to int* to get z
    cout << "Final: x=" << x << ", y=" << y << " and z=" << *z << endl;
    return 0;
}
